<?php require_once __DIR__ . '/../includes/auth.php'; require_once __DIR__ . '/../includes/functions.php'; $user=require_login(); $id=(int)($_GET['id']??0); $stmt=db()->prepare('SELECT * FROM clients WHERE id=? AND user_id=?'); $stmt->execute([$id,$user['id']]); $client=$stmt->fetch(); if(!$client){http_response_code(404); exit('Client not found');} ?>
<!doctype html><html><head><title>Client</title><link rel="stylesheet" href="/assets/css/style.css"></head><body><main class="container"><div class="card"><h1><?= e($client['full_name']) ?></h1><p><strong>Birth date:</strong> <?= e($client['birth_date']) ?></p><p><strong>Phone:</strong> <?= e($client['phone']) ?></p><p><strong>Email:</strong> <?= e($client['email']) ?></p><p><?= nl2br(e($client['notes'])) ?></p><a class="btn" href="/report.php?client_id=<?= $id ?>">Open Report</a></div></main></body></html>
